import SwiftUI
struct ProfilesView:View {@Environment(AppState.self)private var app;@State private var editing:UserProfile?;@State private var creating=false
 var body:some View{NavigationStack{List{if let p=app.profiles.selectedProfile{Section("Current profile"){ProfileCard(profile:p,selected:true);Button("Edit Profile"){editing=p};Button("Switch Profile"){editing=nil}}}Section("Who are you planning for?"){ForEach(app.profiles.profiles){p in Button{app.profiles.select(p.id)}label:{ProfileCard(profile:p,selected:p.id==app.profiles.selectedProfileID)}};Button("Add Another Profile",systemImage:"plus"){creating=true}}Section("Privacy & settings"){NavigationLink("Privacy and optional data"){LegalView()};LabeledContent("Health records","Not connected")}}.navigationTitle("Profile").toolbar{Button{creating=true}label:{Image(systemName:"plus")}}.sheet(item:$editing){p in ProfileEditorView(profile:p,onSave:app.profiles.update,onDelete:{app.profiles.delete(p)})}.sheet(isPresented:$creating){ProfileEditorView(profile:.init(name:"",relationship:.myself),onSave:app.profiles.add,onDelete:nil)}}}
}
struct ProfileCard:View{let profile:UserProfile;let selected:Bool;var body:some View{HStack{VStack(alignment:.leading){Text(profile.name).font(.headline);Text([profile.age.map{"Age \($0)"},profile.source == .synthetic ? "Demo profile":nil].compactMap{$0}.joined(separator:" · ")).font(.subheadline).foregroundStyle(.secondary)};Spacer();if selected{Image(systemName:"checkmark.circle.fill").foregroundStyle(.tint)}}.contentShape(Rectangle())}}
struct ProfileEditorView:View{@Environment(\.dismiss)private var dismiss;@State var profile:UserProfile;let onSave:(UserProfile)->Void;let onDelete:(()->Void)?;@State private var ageText="";let medical=["Asthma","COPD","Interstitial lung disease","Bronchiectasis","Cystic fibrosis","Hypertension","High cholesterol","Atrial fibrillation / arrhythmia","Heart failure","Previous stroke","Peripheral vascular disease","Coronary heart disease","Diabetes"];let mental=["Depressive disorder","Anxiety disorder","Bipolar disorder","Schizophrenia"]
 var body:some View{NavigationStack{Form{Section("Profile"){TextField("Name",text:$profile.name);Picker("Relationship",selection:$profile.relationship){ForEach(ProfileRelationship.allCases){Text($0.label).tag($0)}};TextField("Age",text:$ageText).keyboardType(.numberPad);TextField("Home ZIP code",text:Binding(get:{profile.homeZipCode ?? ""},set:{profile.homeZipCode=$0.isEmpty ? nil:$0})).keyboardType(.numberPad);Text("Home ZIP helps show conditions around home. Activity addresses are entered separately.").font(.caption).foregroundStyle(.secondary)};TagInput(title:"Medical conditions",suggestions:medical,values:$profile.medicalConditions);TagInput(title:"Mental or cognitive conditions",suggestions:mental,values:$profile.mentalConditions);TagInput(title:"Medications",suggestions:["Lisinopril","Albuterol","Metformin","Atorvastatin"],values:$profile.medications);if let onDelete{Section{Button("Delete Profile",role:.destructive){onDelete();dismiss()}}}}.navigationTitle(profile.name.isEmpty ? "Create Profile":"Edit Profile").toolbar{ToolbarItem(placement:.cancellationAction){Button("Cancel"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("Save"){profile.age=Int(ageText);onSave(profile);dismiss()}.disabled(profile.name.trimmingCharacters(in:.whitespaces).isEmpty || (Int(ageText) ?? 0)>120)}}.onAppear{ageText=profile.age.map(String.init) ?? ""}}}
}
